def match(orders):
    import heapq

    book = {}  # id -> order dict with side, price, qty, seq
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    seq_counter = 0
    trades = []

    def add_to_book(order):
        book[order['id']] = order
        if order['side'] == 'buy':
            heapq.heappush(buy_heap, (-order['price'], order['seq'], order['id']))
        else:
            heapq.heappush(sell_heap, (order['price'], order['seq'], order['id']))

    def get_top(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            order = book.get(oid)
            if order is None or order['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return order
        return None

    for o in orders:
        typ = o[0]
        if typ == 'cancel':
            oid = o[1]
            if oid in book:
                del book[oid]
            continue

        oid = o[1]
        side = o[2]
        if typ == 'market':
            price = None
            qty = o[3]
        else:
            price = o[3]
            qty = o[4]

        seq_counter += 1
        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0:
            top = get_top(opp_heap)
            if top is None:
                break

            if typ == 'market':
                cross = True
            else:
                if side == 'buy':
                    cross = price >= top['price']
                else:
                    cross = price <= top['price']

            if not cross:
                break

            trade_qty = min(remaining, top['qty'])

            if side == 'buy':
                trades.append([oid, top['id'], top['price'], trade_qty])
            else:
                trades.append([top['id'], oid, top['price'], trade_qty])

            remaining -= trade_qty
            top['qty'] -= trade_qty

            if top['qty'] == 0:
                del book[top['id']]
                heapq.heappop(opp_heap)
            # else, top stays at front of heap for next iteration

        if typ == 'limit' and remaining > 0:
            order = {'id': oid, 'side': side, 'price': price, 'qty': remaining, 'seq': seq_counter}
            add_to_book(order)
        # ioc and market orders discard any remaining quantity

    return trades

